import sys

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx += 1
    M = int(input[idx]); idx += 1

    adj = [[] for _ in range(N + 1)]
    edges = []
    for _ in range(M):
        s = int(input[idx]); idx += 1
        t = int(input[idx]); idx += 1
        adj[s].append(t)
        edges.append((s, t))

    original_E = [0.0] * (N + 1)
    for u in range(N - 1, 0, -1):
        k = len(adj[u])
        if k == 0:
            original_E[u] = 0.0
        else:
            sum_E = 0.0
            for v in adj[u]:
                sum_E += original_E[v]
            original_E[u] = 1.0 + sum_E / k

    min_E = original_E[1]

    for s, t in edges:
        if len(adj[s]) == 1:
            continue
        modified_E = [0.0] * (N + 1)
        for u in range(N - 1, 0, -1):
            if u == s:
                outgoing = [v for v in adj[u] if v != t]
            else:
                outgoing = adj[u]
            k = len(outgoing)
            if k == 0:
                modified_E[u] = 0.0
            else:
                sum_E = 0.0
                for v in outgoing:
                    sum_E += modified_E[v]
                modified_E[u] = 1.0 + sum_E / k
        current_E = modified_E[1]
        if current_E < min_E:
            min_E = current_E

    print("{0:.10f}".format(min_E))

