from itertools import permutations

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx += 1
    M = int(input[idx]); idx += 1
    w = list(map(int, input[idx:idx+N]))
    idx += N
    bridge_parts = []
    for _ in range(M):
        l = int(input[idx])
        v = int(input[idx+1])
        bridge_parts.append((l, v))
        idx += 2

    min_distance = float('inf')

    for perm in permutations(range(1, N+1)):
        groups = []
        for i in range(N):
            current_sum = 0
            for j in range(i, N):
                current_sum += w[perm[j]-1]
                if j - i + 1 >= 2:
                    groups.append(current_sum)
        required = 0
        for (l_i, v_i) in bridge_parts:
            current_max_l = 0
            for group_sum in groups:
                if group_sum > v_i:
                    if l_i > current_max_l:
                        current_max_l = l_i
            if current_max_l > 0:
                required = max(required, current_max_l)
        if required < min_distance:
            min_distance = required

    if min_distance == float('inf'):
        print(-1)
    else:
        print(min_distance)

