    N = int(input[0])
    A = list(map(int, input[1:N+1]))
    prefix = [0] * (N + 1)
    for i in range(N):
        prefix[i+1] = prefix[i] + A[i]
    total = prefix[-1]

    def get_candidates(prefix, target, start, end):
        pos = bisect.bisect_left(prefix, target, start, end + 1)
        candidates = set()
        for i in range(pos-2, pos+3):
            if start <= i <= end:
                candidates.add(i)
        return list(candidates)

    candidates_i = get_candidates(prefix, total / 4, 1, N-3)
    candidates_j = get_candidates(prefix, total / 2, 1, N-2)
    candidates_k = get_candidates(prefix, 3 * total / 4, 1, N-1)

    min_diff = float('inf')
    for i in candidates_i:
        for j in candidates_j:
            if j <= i:
                continue
            for k in candidates_k:
